-- Clear Talks CT-02h: STAGED ONLY, no hosted changes.
-- Filename generated by pinned Supabase CLI 3.2.0 in GitHub Actions 45304812323.
-- Depends on CT-02b/c/e/f/g, approved owner/grants and full cutover tests.
-- IMPORTANT: Do not apply to hosted restored DB without backup+history
-- reconciliation, negative Auth/JWT/Storage QA and express user approval.
begin;

-- Homepage draft access is separate from publishing live placements.
drop policy if exists homepage_layout_drafts_insert_editor on public.homepage_layout_drafts;
drop policy if exists homepage_layout_drafts_select_editor on public.homepage_layout_drafts;
drop policy if exists homepage_layout_drafts_update_editor on public.homepage_layout_drafts;
create policy ct02h_layout_draft_read on public.homepage_layout_drafts for select to authenticated using (
  newsroom_private.has_staff_permission('homepage.view_editor')
  or newsroom_private.has_staff_permission('homepage.edit')
);
create policy ct02h_layout_draft_insert on public.homepage_layout_drafts for insert to authenticated with check (
  newsroom_private.has_staff_permission('homepage.edit')
  and updated_by=(select auth.uid())
);
create policy ct02h_layout_draft_update on public.homepage_layout_drafts for update to authenticated using (
  newsroom_private.has_staff_permission('homepage.edit')
) with check (
  newsroom_private.has_staff_permission('homepage.edit')
  and updated_by=(select auth.uid())
);

-- The original homepage_slots_select_public policy is preserved unchanged.
-- Every direct mutation of LIVE layout rows requires both edit AND publish.
drop policy if exists homepage_slots_insert_editor on public.homepage_slots;
drop policy if exists homepage_slots_update_editor on public.homepage_slots;
drop policy if exists homepage_slots_delete_editor on public.homepage_slots;
drop policy if exists homepage_slots_select_editor on public.homepage_slots;
create policy ct02h_slots_staff_read on public.homepage_slots for select to authenticated using (
  newsroom_private.has_staff_permission('homepage.view_editor')
  or newsroom_private.has_staff_permission('homepage.edit')
);
create policy ct02h_slots_insert on public.homepage_slots for insert to authenticated with check (
  newsroom_private.has_staff_permission('homepage.edit')
  and newsroom_private.has_staff_permission('homepage.publish')
  and created_by=(select auth.uid()) and updated_by=(select auth.uid())
);
create policy ct02h_slots_update on public.homepage_slots for update to authenticated using (
  newsroom_private.has_staff_permission('homepage.edit')
  and newsroom_private.has_staff_permission('homepage.publish')
) with check (
  newsroom_private.has_staff_permission('homepage.edit')
  and newsroom_private.has_staff_permission('homepage.publish')
  and updated_by=(select auth.uid())
);
create policy ct02h_slots_delete on public.homepage_slots for delete to authenticated using (
  newsroom_private.has_staff_permission('homepage.edit')
  and newsroom_private.has_staff_permission('homepage.publish')
);

-- Preserve breaking_news_select_public: active, time-window-limited headlines.
-- Their updates and deletion change the LIVE reader-facing homepage.
drop policy if exists breaking_news_insert_editor on public.breaking_news;
drop policy if exists breaking_news_update_editor on public.breaking_news;
drop policy if exists breaking_news_delete_editor on public.breaking_news;
drop policy if exists breaking_news_select_editor on public.breaking_news;
create policy ct02h_breaking_staff_read on public.breaking_news for select to authenticated using (
  newsroom_private.has_staff_permission('homepage.view_editor')
  or newsroom_private.has_staff_permission('homepage.edit')
);
create policy ct02h_breaking_insert on public.breaking_news for insert to authenticated with check (
  newsroom_private.has_staff_permission('homepage.edit')
  and newsroom_private.has_staff_permission('homepage.publish')
  and created_by=(select auth.uid()) and updated_by=(select auth.uid())
);
create policy ct02h_breaking_update on public.breaking_news for update to authenticated using (
  newsroom_private.has_staff_permission('homepage.edit')
  and newsroom_private.has_staff_permission('homepage.publish')
) with check (
  newsroom_private.has_staff_permission('homepage.edit')
  and newsroom_private.has_staff_permission('homepage.publish')
