create policy ct02h_breaking_delete on public.breaking_news for delete to authenticated using (
  newsroom_private.has_staff_permission('homepage.edit')
  and newsroom_private.has_staff_permission('homepage.publish')
);

-- Prevent direct authenticated manipulation of publication audit author IDs.
create function newsroom_private.guard_homepage_actor()
returns trigger language plpgsql security invoker set search_path='' as $fn$
begin
  if current_user <> 'authenticated' then return new; end if;
  if tg_op='INSERT' then
    if new.created_by is distinct from (select auth.uid())
       or new.updated_by is distinct from (select auth.uid()) then
      raise exception 'Homepage actor must match authenticated account'
        using errcode='42501';
    end if;
  elsif tg_op='UPDATE' then
    if new.created_by is distinct from old.created_by
      or new.updated_by is distinct from (select auth.uid()) then
      raise exception 'Homepage creator immutable and updater must match account'
        using errcode='42501';
    end if;
  end if;
  return new;
end;
$fn$;
create trigger ct02h_slots_actor_guard
  before insert or update on public.homepage_slots for each row
  execute function newsroom_private.guard_homepage_actor();
create trigger ct02h_breaking_actor_guard
  before insert or update on public.breaking_news for each row
  execute function newsroom_private.guard_homepage_actor();
revoke all on function newsroom_private.guard_homepage_actor() from public,anon,authenticated;

-- Byline records are editorial presentation, not Auth or staff membership.
-- Preserve visible public bylines and account's own read policy; only
-- verified byline managers may edit, create, hide or delete any byline.
drop policy if exists "Editors can update editorial profiles" on public.editorial_profiles;
drop policy if exists editorial_profiles_update_editor on public.editorial_profiles;
drop policy if exists editorial_profiles_insert_editor on public.editorial_profiles;
drop policy if exists editorial_profiles_delete_editor on public.editorial_profiles;
drop policy if exists editorial_profiles_select_editor on public.editorial_profiles;
create policy ct02h_bylines_staff_read on public.editorial_profiles for select to authenticated using (
  newsroom_private.has_staff_permission('byline.view')
  or newsroom_private.has_staff_permission('byline.manage')
);
create policy ct02h_bylines_insert on public.editorial_profiles for insert to authenticated with check (
  newsroom_private.has_staff_permission('byline.manage')
);
create policy ct02h_bylines_update on public.editorial_profiles for update to authenticated using (
  newsroom_private.has_staff_permission('byline.manage')
) with check (
  newsroom_private.has_staff_permission('byline.manage')
);
create policy ct02h_bylines_delete on public.editorial_profiles for delete to authenticated using (
  newsroom_private.has_staff_permission('byline.manage')
);

