-- Article taxonomy links may NOT be altered solely by a legacy author flag.
-- Assigned staff can edit links only on their active assigned stories. On a
-- published story, the additional story.publish capability is required.
drop policy if exists story_categories_insert_staff on public.story_categories;
drop policy if exists story_categories_delete_staff on public.story_categories;
drop policy if exists story_tags_insert_staff on public.story_tags;
drop policy if exists story_tags_delete_staff on public.story_tags;

create policy ct02h_story_categories_insert on public.story_categories for insert to authenticated with check (
  (newsroom_private.has_staff_permission('story.edit_all',story_id)
   or newsroom_private.has_staff_permission('story.edit_assigned',story_id))
  and exists (select 1 from public.stories s where s.id=story_id
    and (s.status <> 'published'
      or newsroom_private.has_staff_permission('story.publish',story_id)))
);
create policy ct02h_story_categories_delete on public.story_categories for delete to authenticated using (
  (newsroom_private.has_staff_permission('story.edit_all',story_id)
   or newsroom_private.has_staff_permission('story.edit_assigned',story_id))
  and exists (select 1 from public.stories s where s.id=story_id
    and (s.status <> 'published'
      or newsroom_private.has_staff_permission('story.publish',story_id)))
);
create policy ct02h_story_tags_insert on public.story_tags for insert to authenticated with check (
  (newsroom_private.has_staff_permission('story.edit_all',story_id)
   or newsroom_private.has_staff_permission('story.edit_assigned',story_id))
  and exists (select 1 from public.stories s where s.id=story_id
    and (s.status <> 'published'
      or newsroom_private.has_staff_permission('story.publish',story_id)))
);
create policy ct02h_story_tags_delete on public.story_tags for delete to authenticated using (
  (newsroom_private.has_staff_permission('story.edit_all',story_id)
   or newsroom_private.has_staff_permission('story.edit_assigned',story_id))
  and exists (select 1 from public.stories s where s.id=story_id
    and (s.status <> 'published'
      or newsroom_private.has_staff_permission('story.publish',story_id)))
);

-- Preserve the existing invoker, validation, atomic story placement replacement
-- and synchronized editor-draft transaction verbatim from restored live DB.
-- New authorization block verifies caller and requires independent publish
-- permission before any DELETE or INSERT can occur.
CREATE OR REPLACE FUNCTION public.publish_homepage_layout(p_selections jsonb, p_user_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  inserted_count integer;
BEGIN
  -- CT-02h: authenticate the caller rather than trusting p_user_id.
  -- SECURITY INVOKER and existing atomic homepage operations are preserved.
  IF (select auth.uid()) IS NULL
     OR (select auth.uid()) IS DISTINCT FROM p_user_id
     OR NOT newsroom_private.has_staff_permission(
       'homepage.edit'::public.staff_capability_key)
     OR NOT newsroom_private.has_staff_permission(
       'homepage.publish'::public.staff_capability_key)
  THEN
    RAISE EXCEPTION 'A current authorized homepage publisher is required'
      USING ERRCODE='42501';
  END IF;

  IF jsonb_typeof(p_selections) <> 'array' THEN
    RAISE EXCEPTION
      'Homepage selections must be a JSON array.';
  END IF;


  /*
   * Main Front Page scope.
   *
   * A story may appear only once in the main layout.
   * Headline Bar placements are excluded from this scope.
   */
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_selections) AS item
    WHERE
      item->>'slot' <> 'headline_bar'
    GROUP BY
      item->>'storyId'
    HAVING
      count(*) > 1
  ) THEN
    RAISE EXCEPTION
      'A story cannot appear more than once on the front page.';
  END IF;


  /*
   * Headline Bar scope.
   *
   * A story may appear only once inside the Headline Bar.
   */
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_selections) AS item
    WHERE
      item->>'slot' = 'headline_bar'
    GROUP BY
      item->>'storyId'
    HAVING
      count(*) > 1
  ) THEN
    RAISE EXCEPTION
      'A story cannot appear more than once in the headline bar.';
  END IF;


  /*
   * A slot position can contain only one story.
   */
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_selections) AS item
    GROUP BY
      item->>'slot',
      item->>'position'
    HAVING
      count(*) > 1
  ) THEN
    RAISE EXCEPTION
      'A homepage position cannot contain more than one story.';
  END IF;


  /*
   * Replace all currently published homepage placements.
   *
   * WHERE true is intentional here because publishing replaces
   * the complete layout.
   */
  DELETE FROM public.homepage_slots
  WHERE true;


  INSERT INTO public.homepage_slots (
    slot,
    story_id,
    position,
    category_id,
    active,
    created_by,
    updated_by
  )
  SELECT
    (item->>'slot')::public.homepage_slot_type,

    (item->>'storyId')::uuid,

    COALESCE(
      (item->>'position')::integer,
      0
    ),

    NULLIF(
      item->>'categoryId',
      ''
    )::uuid,

    true,

    p_user_id,

    p_user_id

  FROM
    jsonb_array_elements(
      p_selections
    ) AS item

  JOIN public.stories AS story
    ON story.id =
      (item->>'storyId')::uuid

   AND story.status =
      'published';


  GET DIAGNOSTICS
    inserted_count =
      ROW_COUNT;


  IF inserted_count <>
     jsonb_array_length(
       p_selections
     )
  THEN
    RAISE EXCEPTION
      'Every homepage selection must reference a published story.';
  END IF;


  /*
   * Keep the shared editor draft synchronized
   * with the newly published layout.
   */
  INSERT INTO public.homepage_layout_drafts (
    id,
    selections,
    updated_by,
    updated_at
  )
  VALUES (
    'current',
    p_selections,
    p_user_id,
    now()
  )

  ON CONFLICT (id)
  DO UPDATE SET
    selections =
      EXCLUDED.selections,

    updated_by =
      EXCLUDED.updated_by,

    updated_at =
      now();

END;
$function$;

revoke all on function public.publish_homepage_layout(jsonb,uuid) from public, anon, authenticated;
grant execute on function public.publish_homepage_layout(jsonb,uuid) to authenticated;
commit;
